# longest substring wihtout repeating characters

str_ = "abccabdcabcc" 

def isunq(wnd_):
    if len(wnd) == 1:
        return True
    dict={}
    for e in wnd_:
        dict[e] = dict.get(e, 0) + 1
    if max(dict.values())>1:
        return False
    else:
        return True

cnt = 1
left = 0
right = 1

while right < len(str_):
    wnd = str_[left:right]
    
    if isunq(wnd):
        right +=1
        cnt = max(len(wnd), cnt)
        print(wnd)
    else:
        left +=1
print(cnt)


