# 104. Maximum Depth of Binary Tree
# DFS - for tree

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val=val
        self.left=left
        self.right = right

Node20 = TreeNode(20,TreeNode(15), TreeNode(7))
root = TreeNode(3, TreeNode(9), Node20)

def get_children(root):
    if root is None:
        return None
    delta = ["right","left" ]
    for child in delta:
        yield getattr(root, child)

def dfs_f (root):
    for child in get_children(root):
        # c = child.val if child is not None else None
        # print(c)
        dfs_f(child)

dfs_f(root)
# good stuff. but difficult to get depth since left and right are handled individually

# AlgoMonster or Niits: https://youtu.be/hzvoLZatGYw?t=53
def maxDepth (root):

    def dfs(root):
        if not root: # check if None
            return 0
        return 1+ max(dfs(root.left), dfs(root.right))
    
    return 0 if not root else dfs(root)

print(maxDepth(Node20))

