# 219*250 # 109 islands, runs out of time if visited is []

# beats 14% in time 5% in space

# leet solution - O(m x n)time, O(1) space
# Note the subtle guard clause in def dfs() to prevent invalid indexing before grid[i][j] is accessed
def numIslands(self, grid):
    if not grid:
        return 0
        
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                self.dfs(grid, i, j)
                count += 1
    return count

def dfs(self, grid, i, j):
    if i<0 or j<0 or i>=len(grid) or j>=len(grid[0]) or grid[i][j] != '1':
        return # guard clause to prevent invalid indexing
    grid[i][j] = '#'
    self.dfs(grid, i+1, j)
    self.dfs(grid, i-1, j)
    self.dfs(grid, i, j+1)
    self.dfs(grid, i, j-1)

# # END leet solution

def testfunc():
    i,j = 7,7
    if i>4 or grid[i][j] == '1':
        print("True")

testfunc()

